body.script:
//
(function () {
"use strict";

var BASE      = "https://cdn.jsdelivr.net/gh/devmidnightst/nocturnesinglefile@main/";
var SRC       = BASE + "index.html";
var CACHE_KEY = "solaris_html_cache";

var boot = document.getElementById("boot");
var msg  = document.getElementById("bootMsg");
var app  = document.getElementById("app");

// Strip injected ad / redirect scripts from the remote HTML before it runs.
// NOTE: "luminsdk" is the legitimate game-loader SDK and must NOT be stripped.
    var AD_HOSTS = /(effectivecpmnetwork|noct-ad-timer)/i;
    // Runtime cleaner injected into the loader so per-game HTML (srcdoc) is
    // scrubbed of in-game ads before it renders into the game viewer iframe.
    var GAME_AD_CLEANER =
        '<scr'+'ipt>window.__adClean=function(h){try{' +
            'h=String(h||"");' +
            'var AD=/(effectivecpmnetwork|noct-ad|h5Sdk|googlesyndication|doubleclick|googleadservices|pagead|adsbygoogle|adsterra|propellerads|popcash|popads|hilltopads|onclickads|\\/ads?\\/)/i;' +
            'h=h.replace(/<scr'+'ipt\\b[^>]*\\bsrc=["\']([^"\']*)["\'][^>]*>\\s*<\\/scr'+'ipt>/gi,function(t){return AD.test(t)?"":t;});' +
            'h=h.replace(/<div\\s+id=["\']sidebarad\\d+["\'][^>]*>[\\s\\S]*?<\\/div>\\s*<\\/div>/gi,"");' +
            'h=h.replace(/<scr'+'ipt\\b(?![^>]*\\bsrc=)[^>]*>([\\s\\S]*?)<\\/scr'+'ipt>/gi,function(t,b){return (/requestFullscreen/i.test(b)&&/setInterval/i.test(b))?"":t;});' +
        '}catch(e){}return h;};<\/scr'+'ipt>';

function sanitize(html) {
    html = html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, function (tag) {
        return AD_HOSTS.test(tag) ? "" : tag;
    });
    // Rebrand the remote content: Nocturne -> Solaris Mini
    html = html.replace(/Nocturne/g, "Solaris Mini");

    // Inject sanitized game HTML instead of the raw ad-laden game page.
    html = html.replace(/vFrame\.srcdoc\s*=\s*h\b/g, "vFrame.srcdoc=window.__adClean(h)");
    // Block popup / redirect ads inside game frames.
    html = html.replace(/\ballow-popups allow-popups-to-escape-sandbox /g, "");
    // Lumin games dropped the sandbox entirely; restore a restrictive one so games
    // still run but cannot open popups or navigate the top window (redirect ads).
    html = html.replace(
        /vFrame\.removeAttribute\(\s*["\']sandbox["\']\s*\)\s*;/g,
        'vFrame.setAttribute("sandbox","allow-scripts allow-same-origin allow-forms allow-pointer-lock allow-orientation-lock");'
    );

    // Define the cleaner inside the loader document before its scripts run.
    if (html.indexOf("__adClean") !== -1 && html.indexOf("window.__adClean=function") === -1) {
        html = html.replace(/<head([^>]*)>/i, "<head$1>" + GAME_AD_CLEANER);
    }
    return html;
}

function inject(html) {
    html = sanitize(html);
    if (!/<base\b/i.test(html)) {
        html = html.replace(/<head([^>]*)>/i, '<head$1><base href="' + BASE + '">');
    }
    app.srcdoc = html;
    app.classList.add("ready");
    boot.classList.add("gone");
    document.title = "Solaris Mini";
}

function fail(reason) {
    boot.classList.remove("gone");
    boot.innerHTML =
        '<svg class="logo" width="44" height="44" viewBox="0 0 44 44" xmlns="http://www.w3.org/2000/svg" style="filter:drop-shadow(0 0 10px #b8b0da)"><defs><radialGradient id="logo-lg" cx="38%" cy="36%" r="74%"><stop offset="0%" stop-color="#f1eeff"/><stop offset="100%" stop-color="#b8b0da"/></radialGradient></defs><circle cx="22" cy="22" r="22" fill="url(#logo-lg)"/><circle cx="35" cy="11" r="18.5" fill="#05060d"/></svg>' +
        '<div class="err">Couldn\'t reach Solaris Mini.<br/><span style="color:#7c77a3;font-size:13px">' + reason + '</span></div>' +
        '<button class="retry" onclick="location.reload()">Try again</button>';
}

function fetchFresh(onSuccess, onFail) {
    fetch(SRC, { cache: "no-store" })
        .then(function (r) {
            if (!r.ok) throw new Error("CDN returned " + r.status);
            return r.text();
        })
        .then(function (html) {
            if (html.length < 500) throw new Error("Response looked empty.");
            try { localStorage.setItem(CACHE_KEY, html); } catch (e) {}
            onSuccess(html);
        })
        .catch(onFail);
}

function load() {
    var cached;
    try { cached = localStorage.getItem(CACHE_KEY); } catch (e) {}

    if (cached && cached.length > 500) {
        // Serve cache immediately, refresh in background
        inject(cached);
        fetchFresh(function (html) {
            // silently update cache; reload only if content changed
            if (html !== cached) {
                try { localStorage.setItem(CACHE_KEY, html); } catch (e) {}
            }
        }, function () { /* ignore background refresh failures */ });
    } else {
        // No cache — fetch normally and show loading screen
        setTimeout(function () { if (!app.classList.contains("ready")) msg.textContent = "Still loading…"; }, 4000);
        fetchFresh(inject, function (e) {
            fail(e && e.message ? e.message : "Network error.");
        });
    }
}

load();

})();
//
